    const R = (k, css, html) => `<div data-k="${k}" style="position:relative;border-radius:6px;transition:box-shadow .25s, background .25s;${css}">${html}</div>`;
    view.innerHTML = R('html', 'padding:10px', `<div style="font:500 11px ${GMONO};color:${I.mute};margin:0 0 8px 2px" data-lbl="html">div · padding-bottom 56.25%</div>`
      + R('player', 'overflow:hidden', `<div style="position:relative;aspect-ratio:16/9;${art(I.rich)}">${disc(56)}${R('title', 'position:absolute;left:12px;top:10px;padding:2px 4px', `<span style="font:500 14px ${SANS};color:#fff">Sample video title</span>`)}${R('duration', 'position:absolute;right:12px;bottom:12px;padding:2px 6px;background:rgba(0,0,0,.6)', `<span style="font:500 12px ${GMONO};color:#fff">3:33</span>`)}${R('ratio', 'position:absolute;right:-1px;top:0;bottom:0;width:26px', `<div style="position:absolute;inset:0;display:grid;place-items:center"><span style="writing-mode:vertical-rl;font:500 10px ${GMONO};color:rgba(255,255,255,.85)">16 : 9</span></div>`)}</div>`)
      + `<div style="display:grid;grid-template-columns:76px 1fr;gap:12px;align-items:center;margin-top:10px">${R('thumb', 'padding:3px', `<div style="aspect-ratio:4/3;border-radius:4px;${art(I.rich, 200)}"></div>`)}<div>${R('site', 'display:inline-block;padding:1px 4px', `<span style="font:600 13px ${SANS};color:${I.ink}">YouTube</span>`)}${R('author', 'display:inline-block;padding:1px 4px', `<span style="font:400 13px ${SANS};color:${I.mute}">Sample channel</span>`)}${R('medium', 'display:inline-block;padding:1px 4px', `<span style="font:500 11px ${GMONO};color:${I.rich}">video</span>`)}<div>${R('url', 'display:inline-block;padding:1px 4px', `<span style="font:400 11px ${GMONO};color:${I.mute}">youtube.com/watch?v=dQw4w9WgXcQ</span>`)}</div></div></div>`
      + R('lazy', 'margin-top:8px;padding:4px 6px;display:inline-block', `<span style="font:500 11px ${GMONO};color:${I.mute}">embed.js · sizing + lazy loading</span>`));
