    return B().block(s, I, { eyebrow: 'Preview API and oEmbed', tone: 'rich', title: 'One request, a usable result for any URL', paras: ['The Iframely API returns the embed HTML, the media type, thumbnails, metadata and the aspect ratio for any URL. The oEmbed API returns the same in the oEmbed format your editor or CMS may already expect.', 'Where a provider has an embed, you get the player. Where it does not, you get a summary card built from Open Graph, Twitter Cards and structured data. You are not billed for URLs that return nothing useful.'] }, { el: g, text: F.api.map(x => x[0]).join('\n') });
