    const chat = `<div style="padding:12px 14px">${['Dev', 'Mo', 'Kai', 'Lu', 'Ray'].map((n, i) => `<div style="display:grid;grid-template-columns:20px 1fr;gap:8px;margin-bottom:6px;opacity:${1 - i * .08}"><i style="width:20px;height:20px;border-radius:5px;background:${mix(I.surf, I.preview, .15 + i * .1)}"></i><div><span style="font:600 11px ${SANS};color:${I.ink}">${n}</span>${i < 2 ? mini : `<span style="font:400 11px ${SANS};color:${I.mute}"> shared the same link</span>`}</div></div>`).join('')}</div><div style="position:absolute;right:12px;top:12px">${pill(I, '5 shares · 1 hit', I.preview, 1)}</div>`;
