    let n = 0; const box = H(`${panel(I, 14)}overflow:hidden`);
    const draw = () => { box.innerHTML = `<div style="display:flex;gap:10px;align-items:center;padding:12px 16px;box-shadow:inset 0 -1px 0 ${I.line};font:400 12px ${GMONO};color:${I.body};flex-wrap:wrap"><span style="color:${I.data};font-weight:600">GET</span>en.wikipedia.org/wiki/Oembed<span style="margin-left:auto;display:flex;gap:6px">${pill(I, 'assist', I.data)}${pill(I, 'reference', I.mute)}${pill(I, okI(I.good) + 'signed', I.good)}</span></div>`
        + P.map(([k, c, why], i) => `<div style="display:grid;grid-template-columns:80px 1fr auto;gap:12px;align-items:center;padding:12px 16px;box-shadow:inset 0 -1px 0 ${I.faint};opacity:${i < n ? 1 : .18};transform:translateY(${i < n ? 0 : 6}px);transition:opacity .35s, transform .35s"><span style="font:600 13px ${GMONO};color:${I.data}">${k}</span><span style="font:400 13px ${SANS};color:${I.body};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${c.replace('\\n\\n', ' ')}</span><span style="font:400 11px ${SANS};color:${I.mute};text-align:right">${why}</span></div>`).join('')
        + `<div style="display:flex;gap:10px;align-items:center;padding:14px 16px;background:${n > 5 ? mix(I.surf, I.data, I.dark ? .16 : .07) : 'transparent'};transition:background .4s;opacity:${n > 5 ? 1 : .18}"><span style="font:600 13px ${GMONO};color:${I.data}">access</span><span style="font:400 12px ${SANS};color:${I.body}">CC BY-SA 4.0 · robots.txt 200 · max-image-preview: standard</span><span style="margin-left:auto">${pill(I, 'all 5 allowed', I.data, 1)}</span></div>`; };
